package main

import (
	"os/exec"
	"testing"
)

// TestTreeCoverage keeps generated/build variants in scope and tests/fixtures out.
func TestTreeCoverage(t *testing.T) {
	scan := scanFixture(t, map[string]string{
		"internal/source.go":          "// Code generated by fixture. DO NOT EDIT.\n//go:build impossible\n\npackage fixture\nfunc f(a,b,c,d,e,f,g,h int) {}",
		"internal/source_test.go":     "not Go syntax",
		"internal/testdata/broken.go": "not Go syntax",
		"qa/ref/example.go":           "not Go syntax",
		"ops/snapshot.go":             "not Go syntax",
	})
	if len(scan.Declarations) != 1 || !scan.Declarations[0].Generated || len(scan.Declarations[0].Build) != 1 {
		t.Fatalf("source coverage = %+v", scan.Declarations)
	}

	failures := checkPolicy(scan, nil)
	assertPolicyOutcome(t, failures, "unapproved signature")
}

// TestAliasResults distinguishes aliases from defined and unresolved result types.
func TestAliasResults(t *testing.T) {
	cases := []struct {
		name    string
		aliases string
		result  string
		invalid bool
	}{
		{"bool alias chain", "type First = bool; type Second = First", "Second", false},
		{"error alias", "type Failure = error", "Failure", false},
		{"defined boolean", "type Found bool", "Found", true},
		{"string alias", "type Text = string", "Text", true},
		{"qualified type", "", "other.Found", true},
		{"shadowed builtin", "type bool string", "bool", true},
	}
	for _, item := range cases {
		t.Run(item.name, func(t *testing.T) {
			scan := scanFixture(t, map[string]string{
				"aliases.go": "package fixture\n" + item.aliases,
				"source.go":  "package fixture\nfunc f() (value int, found " + item.result + ") { panic(0) }",
			})
			if len(scan.Declarations) != 1 || invalidResults(scan.Declarations[0].Results) != item.invalid {
				t.Fatalf("alias result = %+v", scan.Declarations)
			}
		})
	}
}

// TestLocalAliasScope prevents a callback-local alias from exempting another scope.
func TestLocalAliasScope(t *testing.T) {
	scan := scanFixture(t, map[string]string{
		"aliases.go": "package fixture\ntype Found = bool",
		"source.go":  "package fixture\nfunc outer() { type Found = string; _ = func() (int, Found) { panic(0) } }; func other() (int, Found) { panic(0) }",
	})
	if len(scan.Declarations) != 3 {
		t.Fatalf("declarations = %v", scan.Declarations)
	}

	if !invalidResults(scan.Declarations[1].Results) || invalidResults(scan.Declarations[2].Results) {
		t.Fatalf("alias scopes = %+v", scan.Declarations)
	}
}

// TestBranchIndependent proves a dev self-comparison cannot hide a six-parameter violation.
func TestBranchIndependent(t *testing.T) {
	root := t.TempDir()
	runFixtureGit(t, root, "init", "--initial-branch=dev")
	runFixtureGit(t, root, "-c", "user.name=Fixture", "-c", "user.email=fixture@example.invalid", "commit", "--allow-empty", "-m", "fixture")
	runFixtureGit(t, root, "update-ref", "refs/remotes/origin/dev", "HEAD")
	writeFixture(t, root, "source.go", "package fixture\nfunc f(a,b,c,d,e,f int) {}")
	runFixtureGit(t, root, "add", "source.go")
	runFixtureGit(t, root, "-c", "user.name=Fixture", "-c", "user.email=fixture@example.invalid", "commit", "-m", "violation")
	runFixtureGit(t, root, "update-ref", "refs/remotes/origin/dev", "HEAD")

	for _, branch := range []string{"dev", "feature"} {
		if branch == "feature" {
			runFixtureGit(t, root, "checkout", "-b", branch)
		}

		scan, err := scanSources(root)
		if err != nil {
			t.Fatal(err)
		}

		assertPolicyOutcome(t, checkPolicy(scan, nil), "unapproved signature")
	}
}

func runFixtureGit(t *testing.T, root string, args ...string) {
	t.Helper()

	command := exec.Command("git", args...)

	command.Dir = root
	if output, err := command.CombinedOutput(); err != nil {
		t.Fatalf("git fixture: %s: %v", output, err)
	}
}
